package com.nora.tunnel.data.datastore import android.content.Context import androidx.datastore.preferences.core.* import androidx.datastore.preferences.preferencesDataStore import kotlinx.coroutines.flow.map val Context.dataStore by preferencesDataStore("nora_prefs") object Prefs { val DARK_MODE = stringPreferencesKey("appearance") val AUTO_RECONNECT = booleanPreferencesKey("auto_reconnect") val TIMEOUT = intPreferencesKey("timeout_ms") val RETRY_COUNT = intPreferencesKey("retry_count") } class SettingsRepository(private val context: Context) { val autoReconnect = context.dataStore.data.map { it[Prefs.AUTO_RECONNECT] ?: true } suspend fun setAutoReconnect(v: Boolean) { context.dataStore.edit { it[Prefs.AUTO_RECONNECT]=v } } }

